#!/usr/bin/env python3
"""Execute production Android notification classes with host Context/HTTP/notification collaborators.
Usage: JSON_JAR=/path/org-json.jar python3 chat_notification_client_regression.py
This does not replace an emulator/device test.
"""
import os,subprocess,tempfile
from pathlib import Path
root=Path(__file__).resolve().parents[2];app=root/'app/src/main/java/com/transiva/app'
jar=os.environ['JSON_JAR'];javac=os.environ.get('JAVAC_BIN','javac')
